1|import { useEffect, useState } from 'react';
2|
3|// No backend yet: every operation waits NEXT_PUBLIC_MOCK_LATENCY_MS, and fails
4|// when localStorage 'weave:fail' names it, so loading and error states show.
5|
6|const LATENCY = Number(process.env.NEXT_PUBLIC_MOCK_LATENCY_MS ?? 0);
7|
8|function failing(operation: string): boolean {
9|  try {
10|    return localStorage.getItem('weave:fail') === operation;
11|  } catch {
12|    return false;
13|  }
14|}
15|
16|export async function mockCall(operation: string): Promise<void> {
17|  if (LATENCY > 0) await new Promise((resolve) => setTimeout(resolve, LATENCY));
18|  if (failing(operation)) throw new Error(`${operation} failed`);
19|}
20|
21|/** A read as a page renders it: the data, while it loads, its error, and a retry. */
22|export type Read<T> = { data: T; loading: boolean; error: Error | null; retry: () => void };
23|
24|export function useRead<T>(operation: string, data: T): Read<T> {
25|  const [attempt, setAttempt] = useState(0);
26|  const [status, setStatus] = useState<{ loading: boolean; error: Error | null }>({
27|    loading: LATENCY > 0,
28|    error: null,
29|  });
30|  useEffect(() => {
31|    let live = true;
32|    mockCall(operation).then(
33|      () => live && setStatus({ loading: false, error: null }),
34|      (error: Error) => live && setStatus({ loading: false, error }),
35|    );
36|    return () => {
37|      live = false;
38|    };
39|  }, [operation, attempt]);
40|  const retry = () => {
41|    setStatus({ loading: LATENCY > 0, error: null });
42|    setAttempt((n) => n + 1);
43|  };
44|  return { data, ...status, retry };
45|}

