/**
 * A fixed set, such as four reasons to join: `columns` sets a count that
 * divides it, so no card sits alone in the last row.
 */
const FixedSet = () => (
  <CardList
    aria-label="Reasons to join"
    items={reasons}
    layout="grid"
    columns={2}
    renderItem={(reason) => (
      <>
