};

/**
 * Saved as the user types: `delay` holds `onChange` until typing pauses for
 * 500ms. A new `value` from the parent, like the suggested title, replaces the
 * text and drops an unsent save.
 */
const AutosavedTitle = () => {
  const [title, setTitle] = useState('Launch party');
  const [status, setStatus] = useState('All changes saved');

  const save = (next: string) => {
    setTitle(next);
    setStatus('Saving');
    saveTitle(next).then(() => setStatus('All changes saved'));
  };

  return (
    <div className="flex-col-gap-2 items-start">
      <Input
        label="Event title"
        autoComplete="off"
        delay={500}
        value={title}
        onChange={save}
      />
      <Button variant="base" onClick={() => save('Product launch')}>
        Use suggested title
      </Button>
      <p role="status">{status}</p>
    </div>
  );
};

/** `hint` explains the field in a tooltip, `placeholder` shows an example. */
const PromoCode = () => {
  const [code, setCode] = useState('');

  return (
    <Input
      label="Promo code"
      hint="Codes are on your invitation email"
      placeholder="EARLYBIRD"
      autoComplete="off"
      value={code}
      onChange={setCode}
    />
  );
};

/**
 * A length limit: `maxLength` stops typing at it; the counter sits in
 * `labelRightSlot`, so it doesn't announce on every key.
 */
const Tagline = () => {
  const [tagline, setTagline] = useState('');

  return (
    <Input
      label="Tagline"
      autoComplete="off"
      maxLength={MAX_TAGLINE}
      labelRightSlot={`${tagline.length}/${MAX_TAGLINE}`}
      helpText={`Up to ${MAX_TAGLINE} characters`}
      value={tagline}
      onChange={setTagline}
    />
  );
};

/**
 * A field in a toolbar or table row with no visible label: `aria-label` names
 * it, `tooltip` shows the name on hover, `variant="base"` suits a non-page
 * surface.
 */
const AttendeeNote = () => {
  const [note, setNote] = useState('');

  return (
    <Input
      aria-label="Attendee note"
      tooltip="Only organizers see this note"
      variant="base"
      size="sm"
      placeholder="Add a note"
      autoComplete="off"
      value={note}
      onChange={setNote}
