/**
 * A field that can't be used yet: `disabledWithReason` says what unlocks it.
 */
const RegistrationCode = () => (
  <Input
    label="Registration code"
    disabledWithReason="Codes open when registration starts"
    autoComplete="off"
    value=""
    onChange={() => undefined}
  />
);

/**
 * Content on its way: `loadingWithReason` shows a spinner and says what loads.
 */
const DraftTitle = () => (
  <Input
    label="Title"
    loadingWithReason="Loading your draft"
    autoComplete="off"
    value=""
    onChange={() => undefined}
  />
);

type Address = { address: string };

/**
 * Checking a value on the server: an async `validate` rule runs on each change
 * (`mode: 'onChange'`), and `delay` makes a change a pause in typing. `loading`
 * follows `isValidating`; `success` confirms the address.
 */
const EventAddressField = () => {
  const {
    control,
    handleSubmit,
    formState: { isSubmitting },
  } = useForm<Address>({ mode: 'onChange', defaultValues: { address: '' } });

  return (
    <Form
      onSubmit={handleSubmit(reserveAddress)}
      actions={
        <Button
          type="submit"
          loadingWithReason={isSubmitting ? 'Reserving the address' : undefined}
        >
          Reserve
        </Button>
      }
    >
      <Controller
        name="address"
        control={control}
        rules={{
          required: 'Choose an address',
          validate: async (address) =>
            (await isAddressFree(address)) || 'That address is taken',
        }}
      >
        {({ field, fieldState }) => (
          <Input
            label="Event address"
            autoComplete="off"
            delay={500}
            // Typing stays open while the check runs.
            loading={fieldState.isValidating}
            disableWhileLoading={false}
            success={
              field.value && !fieldState.error && !fieldState.isValidating
                ? 'Available'
                : undefined
            }
            {...field}
          />
        )}
      </Controller>
    </Form>
  );
};

/**
 * Adding items from the keyboard: Enter adds, and `ref` reaches the input to
 * return focus after each add.
 */
const SpeakerList = () => {
  const [speakers, setSpeakers] = useState<string[]>([]);
  const [name, setName] = useState('');
  const inputRef = useRef<HTMLElement>(null);

  const add = () => {
    if (!name.trim()) return;
    setSpeakers([...speakers, name.trim()]);
    setName('');
    inputRef.current?.focus();
  };

  return (
    <div className="flex-col-gap-2 items-start">
      <Input
        ref={inputRef}
        label="Speaker name"
        autoComplete="off"
        value={name}
        onChange={setName}
        onKeyDown={(event) => {
          if (event.key !== 'Enter') return;
          event.preventDefault();
          add();
        }}
      />
      <Button variant="base" onClick={add}>
        Add speaker
      </Button>
      <ul>
        {speakers.map((speaker) => (
          <li key={speaker}>{speaker}</li>
        ))}
      </ul>
    </div>
  );
};

/**
 * Two numbers that must be in order. `error={true}` styles From alone; the
 * message on To is the one announced. `allowNegative={false}` keeps the number
 * keypad on phones.
 */
const PriceFilter = () => {
  const [from, setFrom] = useState<number | null>(20);
  const [to, setTo] = useState<number | null>(10);
  const isInverted = from !== null && to !== null && from > to;

  return (
    <div className="flex-row-gap-4 flex-wrap items-start">
      <NumberInput
        label="From"
        autoComplete="off"
        allowNegative={false}
        leftAddOn="€"
        error={isInverted}
        value={from}
        onChange={setFrom}
      />
      <NumberInput
        label="To"
        autoComplete="off"
        allowNegative={false}
        leftAddOn="€"
        error={isInverted && 'To must not be below From'}
        value={to}
        onChange={setTo}
      />
    </div>
  );
};

/**
 * Whole numbers within a range: `allowDecimal={false}`, `min` and `max` (blur
 * moves the number into them), `delay` to wait for a pause. `warning` flags an
 * allowed value worth a look.
 */
const VenueCapacity = () => {
  const [capacity, setCapacity] = useState<number | null>(120);

