type SignIn = { password: string };

/**
 * Signing in: `autoComplete="current-password"` lets password managers fill it,
 * `labelRightSlot` holds the recovery link, and a failed sign-in goes through
 * `setError`.
 */
const SignInForm = () => {
  const {
    control,
    handleSubmit,
    setError,
    formState: { isSubmitting },
  } = useForm<SignIn>({ defaultValues: { password: '' } });

  const submit = async ({ password }: SignIn) => {
    if (!(await signIn(password))) {
      setError('password', { message: 'That password is not right' });
    }
  };

  return (
    <Form
      onSubmit={handleSubmit(submit)}
      actions={
