 */
const SignInForm = () => {
  const {
    control,
    handleSubmit,
    setError,
    formState: { isSubmitting },
  } = useForm<SignIn>({ defaultValues: { password: '' } });

  const submit = async ({ password }: SignIn) => {
    if (!(await signIn(password))) {
      setError('password', { message: 'That password is not right' });
    }
  };

  return (
    <Form
      onSubmit={handleSubmit(submit)}
      actions={
        <Button
