// Usage: the patterns to copy.
type Ticket = { id: string; name: string; price: number; soldOut?: boolean };

type Session = { id: string; title: string; day: string };

type Registration = { ticketType: string; sessions: string[] };

/**
 * Single and multiple in a form, each through `Controller`: `rules` validate,
 * `validate` checks a list, and a failed rule's message shows below the help
 * text.
 */
const RegistrationForm = () => {
  const {
    control,
    handleSubmit,
    formState: { isSubmitting },
  } = useForm<Registration>({
    defaultValues: { ticketType: '', sessions: [] },
  });

  return (
    <Form
      onSubmit={handleSubmit(registerAttendee)}
      actions={
        <Button
          type="submit"
          loadingWithReason={isSubmitting ? 'Registering…' : undefined}
        >
          Register
        </Button>
      }
    >
      <Controller
        name="ticketType"
        control={control}
        rules={{ required: 'Choose a ticket type' }}
      >
        {({ field }) => (
          <Select label="Ticket type" helpText="Prices include tax" {...field}>
            {tickets.map((ticket) => (
              <SelectOption
                key={ticket.id}
                value={ticket.id}
                label={ticket.name}
              />
            ))}
          </Select>
        )}
      </Controller>
      <Controller
        name="sessions"
        control={control}
        rules={{
          validate: (value) =>
            value.length > 0 || 'Choose at least one session',
        }}
      >
        {({ field }) => (
          <MultiSelect
            label="Sessions"
            helpText="You can change these until the event"
            {...field}
          >
            {sessions.map((session) => (
              <SelectOption
                key={session.id}
                value={session.id}
                label={session.title}
              />
            ))}
          </MultiSelect>
        )}
      </Controller>
    </Form>
  );
};

/**
 * Options with data and states. An extra prop on `SelectOption`, like
 * `price`, reaches `onChange` with the option: type it with
 * `SelectOptionData`. A sold-out option takes `disabledWithReason`, shown on
 * hover.
 */
const TicketTypeSelect = () => {
  const [value, setValue] = useState('');
  const [total, setTotal] = useState<number>();

  return (
    <Select
      label="Ticket"
      helpText={total === undefined ? undefined : `Total: $${total}`}
      value={value}
      onChange={(
        next,
        option: SelectOptionData<string, { price: number }> | undefined,
      ) => {
        setValue(next);
        setTotal(option?.price);
      }}
    >
      {tickets.map((ticket) => (
        <SelectOption
          key={ticket.id}
          value={ticket.id}
          label={ticket.name}
          price={ticket.price}
          disabledWithReason={ticket.soldOut ? 'Sold out' : undefined}
        >
          {ticket.name} (${ticket.price})
        </SelectOption>
      ))}
    </Select>
  );
};

type SortKey = 'date' | 'name' | 'attendees';

const sortLabels: Record<SortKey, string> = {
  date: 'Date',
  name: 'Name',
  attendees: 'Attendees',
};

/**
 * A toolbar control that always has a value: `aria-label` names it.
 * `allowSearch={false}` drops the search field (a letter opens the menu or
 * jumps to a match, as in a native select), `allowClear={false}` keeps a value
 * chosen, `variant="base"` and `look="open"` suit a toolbar.
 */
const SortSelect = () => {
  const [sort, setSort] = useState<SortKey>('date');

  return (
    <Select
      aria-label="Sort events by"
      allowSearch={false}
      allowClear={false}
      variant="base"
      look="open"
      value={sort}
      onChange={(next) => next && setSort(next)}
    >
      {Object.entries(sortLabels).map(([key, label]) => (
        <SelectOption key={key} value={key} label={label} />
      ))}
    </Select>
  );
};

/**
 * MultiSelect filtering on the client: each value is a tag, Backspace in the
 * empty search removes the last, the clear button clears all. `showCheckbox`
 * adds a checkbox before each option, beside the check mark;
 * `showCheckmark={false}` drops the mark.
 */
const TeamFilter = () => {
  const [values, setValues] = useState<string[]>([]);
  return (
    <MultiSelect label="Teams" showCheckbox value={values} onChange={setValues}>
      {teams.map((team) => (
        <SelectOption key={team} value={team} label={team} />
      ))}
    </MultiSelect>
  );
};

const days = ['Friday', 'Saturday', 'Sunday'];

/**
 * A button that acts on the choice, here moving a session to another day:
 * `action` lines it up with the box, so the label stays above both. The same
 * outside a form, as in a toolbar or a filter bar.
 */
const MoveSession = () => {
  const [day, setDay] = useState('');
  const [moved, setMoved] = useState('');
  return (
    <div className="flex-col-gap-2">
      <Select
        label="Move to day"
        allowSearch={false}
        value={day}
        onChange={setDay}
        action={
          <Button
            variant="base" // Moving is the quiet action beside the choice.
            disabledWithReason={day === '' ? 'Pick a day first' : undefined}
            onClick={() => setMoved(`Moved to ${day}`)}
          >
            Move
          </Button>
        }
      >
        {days.map((option) => (
          <SelectOption key={option} value={option} label={option} />
        ))}
      </Select>
      <p role="status">{moved}</p>
    </div>
  );
};

type Venue = { id: string; name: string; city: string };

/**
 * Server search: `onSearch` runs after a pause in typing, the parent renders
 * the matches, and `loading` shows meanwhile. Each answer keeps the text it
 * answers: one to older text is dropped, and loading lasts until an answer
 * matches the last text typed. The saved venue stays an option when the
 * results omit it, so its label shows, not its id.
 */
const VenueSearch = () => {
  const [value, setValue] = useState(savedVenue.id);
  const [search, setSearch] = useState('');
  const [answer, setAnswer] = useState<{ search: string; venues: Venue[] }>();

  useEffect(() => {
    let stale = false;
    searchVenues(search).then((venues) => {
      if (!stale) setAnswer({ search, venues });
    });
    return () => {
      stale = true;
    };
  }, [search]);

  const loading = answer?.search !== search;
  const results = answer?.venues ?? [];
  const listed = results.some(({ id }) => id === value)
    ? results
    : [...results, ...venues.filter(({ id }) => id === value)];

  return (
    <Select
      label="Venue"
      onSearch={setSearch}
      // Usable while loading: the spinner says results are on the way.
      loading={loading}
      value={value}
      onChange={setValue}
    >
      {listed.map((venue) => (
        <SelectOption key={venue.id} value={venue.id} label={venue.name}>
          {venue.name}, {venue.city}
        </SelectOption>
      ))}
    </Select>
  );
};

type Speaker = { id: string; name: string };

/**
 * MultiSelect searching on the server, with `search` controlled so the parent
 * owns the typed text. Loading and stale answers work as in VenueSearch.
 * Chosen speakers the results omit stay options, so their tags keep names.
 */
const SpeakerSearch = () => {
  const [values, setValues] = useState<string[]>([]);
  const [search, setSearch] = useState('');
  const [answer, setAnswer] = useState<{
    search: string;
    speakers: Speaker[];
  }>();

  useEffect(() => {
    let stale = false;
    searchSpeakers(search).then((found) => {
      if (!stale) setAnswer({ search, speakers: found });
    });
    return () => {
      stale = true;
    };
  }, [search]);

  const loading = answer?.search !== search;
  const results = answer?.speakers ?? [];
  const kept = speakers.filter(
    ({ id }) => values.includes(id) && !results.some((item) => item.id === id),
  );

  return (
    <MultiSelect
      label="Speakers"
      search={search}
      onSearch={setSearch}
      // Usable while loading: the spinner says results are on the way.
      loading={loading}
      value={values}
      onChange={setValues}
    >
      {[...kept, ...results].map((speaker) => (
        <SelectOption
          key={speaker.id}
          value={speaker.id}
          label={speaker.name}
        />
      ))}
    </MultiSelect>
  );
};

type Person = { id: string; name: string; role: string };

/**
 * Custom rows and trigger: an option's children draw its row, and
 * `renderTrigger` draws the trigger once something is selected. `label` stays
 * the text search matches and typeahead uses. `md`: its 32px line fits the
 * 28px avatar without growing the box.
 */
const AssigneeSelect = () => {
  const [value, setValue] = useState('');
  return (
    <Select
      label="Assignee"
      placeholder="Unassigned"
      size="md"
      value={value}
      onChange={setValue}
      // The menu is as wide as the trigger: wide enough for the rows.
      className="w-full"
      renderTrigger={({ selected }) => (
        <span className="flex-row-gap-2 items-center">
          <Avatar size="sm" name={selected.label} />
          {selected.label}
        </span>
      )}
    >
      {people.map((person) => (
        <SelectOption key={person.id} value={person.id} label={person.name}>
          <span className="flex-row-gap-2 items-center">
            <Avatar size="sm" name={person.name} />
            {person.name}
            <Tag size="xs">{person.role}</Tag>
          </span>
        </SelectOption>
      ))}
    </Select>
  );
};

/**
 * MultiSelect with `renderTrigger` replacing the tags with a summary, for a
 * filter in a crowded row. It shows once something is selected.
 */
const TrackFilter = () => {
  const [values, setValues] = useState<string[]>([]);
  return (
    <MultiSelect
      label="Tracks"
      allowSearch={false}
      value={values}
      onChange={setValues}
      renderTrigger={({ selected }) => `${selected.length} tracks`}
    >
      {tracks.map((track) => (
        <SelectOption key={track} value={track} label={track} />
      ))}
    </MultiSelect>
  );
};

/**
 * Grouped options: a `SelectGroup` labels its options, here each day's
 * sessions. Search keeps the groups that still match.
 */
const SessionSelect = () => {
  const [value, setValue] = useState('');
  const days = [...new Set(sessions.map(({ day }) => day))];

  return (
    <Select label="Session" value={value} onChange={setValue}>
      {days.map((day) => (
        <SelectGroup key={day} label={day}>
          {sessions
            .filter((session) => session.day === day)
            .map((session) => (
              <SelectOption
                key={session.id}
                value={session.id}
                label={session.title}
              />
            ))}
        </SelectGroup>
      ))}
    </Select>
  );
};

/**
 * Disabled, read-only and loading states, each with a hover reason:
 * `readOnlyWithReason` for a value that can't change here,
 * `disabledWithReason` for a control not available yet, `loadingWithReason`
 * for choices on the way. A Select stays usable while loading unless
 * `disableWhileLoading` is set. Without a reason, `disabled`, `readOnly` and
 * `loading` take `true`.
 */
const EventSettings = () => {
  const [timezone, setTimezone] = useState('Europe/Lisbon');
  const [room, setRoom] = useState('');
  const [currency, setCurrency] = useState('EUR');

  return (
    <div className="flex-col-gap-4 items-start">
      <Select
        label="Timezone"
        readOnlyWithReason="Set by the venue"
        value={timezone}
        onChange={setTimezone}
      >
        {timezones.map((zone) => (
          <SelectOption key={zone} value={zone} label={zone} />
        ))}
      </Select>
      <Select
        label="Room"
        disabledWithReason="Choose a venue first"
        value={room}
        onChange={setRoom}
      >
        {rooms.map((name) => (
          <SelectOption key={name} value={name} label={name} />
        ))}
      </Select>
      <Select
        label="Currency"
        loadingWithReason="Loading rates"
        disableWhileLoading
        value={currency}
        onChange={setCurrency}
      >
        {currencies.map((code) => (
          <SelectOption key={code} value={code} label={code} />
        ))}
      </Select>
    </div>
  );
};

/**
 * Field decoration: `leftIcon`, `hint` (a tooltip from the info icon),
 * `labelRightSlot`, `tooltip` on the box and a `warning` message.
 */
const VisibilitySelect = () => {
  const [value, setValue] = useState('Public');
  return (
    <Select
      label="Visibility"
      leftIcon={<Globe />}
      hint="Who can find this event"
      labelRightSlot={<Tag size="xs">New</Tag>}
      tooltip="Applies to the event page"
      warning={value === 'Public' ? 'Anyone can see this event' : undefined}
      value={value}
      onChange={setValue}
    >
      {visibilities.map((visibility) => (
        <SelectOption key={visibility} value={visibility} label={visibility} />
      ))}
    </Select>
  );
};

/**
 * A unit after the value with `rightAddOn` (`leftAddOn` goes before), and a
 * status from the choice: `success` when it fits the slot, `error` when not.
 * Each status takes a message, or `true` for the style alone.
 */
const SessionLength = () => {
  const [value, setValue] = useState('45');
  const fits = value !== '' && Number(value) <= 60;

  return (
    <Select
      label="Session length"
      rightAddOn="minutes"
      success={fits ? 'Fits the 60-minute slot' : undefined}
      error={
        value !== '' && !fits ? 'Longer than the 60-minute slot' : undefined
      }
      value={value}
      onChange={setValue}
    >
      {sessionLengths.map((length) => (
        <SelectOption key={length} value={length} label={length} />
      ))}
    </Select>
  );
};

export default function SelectRecipe() {
  return (
    <div className="flex-col-gap-6 items-start">
      <RegistrationForm />
      <TicketTypeSelect />
      <SortSelect />
      <TeamFilter />
      <MoveSession />
      <VenueSearch />
      <SpeakerSearch />
      <AssigneeSelect />
      <TrackFilter />
      <SessionSelect />
      <EventSettings />
      <VisibilitySelect />
      <SessionLength />
    </div>
  );
}

// packages/ui/src/Dialog/Dialog.recipe.tsx
// Covers: Dialog, openConfirmationDialog

/**
 * Dialog: a task over the page that waits until it's done or dismissed, like
 * editing a session. `title` names it, children are the body, `footer` holds
 * the actions: nodes, or a function given `close`.
 * openConfirmationDialog: a yes-or-no question, like confirming a delete,
 * awaited from any code; resolves with the result the pressed button sends.
 *
 * When not to use:
 * - A quick edit or details tied to one control, with the page still usable:
 *   Popover.
 * - A yes-or-no question: openConfirmationDialog, not a Dialog with two
 *   buttons.
 * - A long flow, or anything worth linking to: a page of its own.
 *
 * Pitfalls:
 * - Controlled, `open` changes only through `onOpenChange`: pass both.
 *   Uncontrolled, `trigger` opens it; `footer`'s `close` closes it either way.
 * - `closable={false}` removes the close button, Escape and a press outside:
 *   the footer must offer a way out.
 * - A form in the body: the footer sits outside it, so its submit button
 *   takes `form` with the form's `id`.
 * - openConfirmationDialog resolves `undefined` when it can't ask (on the
 *   server, or the dialog fails to render): treat it as not confirmed.
 * - Only the footer closes a confirmation, and only the first `closeDialog`
 *   counts: every button must call it.
 * - A confirmation renders in its own React root: your app's context doesn't
 *   reach its footer. Pass what it needs in.
 */
import { Button } from '@packages/ui/Button';
import {
  Dialog,
  DialogResult,
  openConfirmationDialog,
} from '@packages/ui/Dialog';
import { Controller, Form } from '@packages/ui/Form';
import { Input } from '@packages/ui/Input';
import { Tag } from '@packages/ui/Tag';
import { Pencil } from 'lucide-react';
import React, { useState } from 'react';
import { useForm } from 'react-hook-form';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const agenda = Array.from(
  { length: 40 },
  (_, index) =>
    `${9 + Math.floor(index / 4)}:${String((index % 4) * 15).padStart(2, '0')} Session ${index + 1}`,
);

// Stands in for a request to the server.
const saveSession = (title: string) =>
  new Promise<string>((resolve) => {
    setTimeout(() => resolve(title), 400);
  });

// Usage: the patterns to copy.
/**
 * Uncontrolled: `trigger` opens it. `footer` as a function gets `close`, for
 * Cancel and after the save. `leftIcon` sits before the title.
 */
const EditSession = () => {
  const [title, setTitle] = useState('Opening keynote');

  return (
    <Dialog
      title="Edit session"
      leftIcon={<Pencil />}
      description="Attendees see the change at once."
      trigger={<Button variant="base">Edit session</Button>}
      footer={(close) => (
        <>
          <Button variant="base" onClick={close}>
            Cancel
          </Button>
          <Button onClick={() => saveSession(title).then(close)}>Save</Button>
        </>
      )}
    >
      <Input
        label="Title"
        autoComplete="off"
        value={title}
        onChange={setTitle}
      />
    </Dialog>
  );
};

/**
 * Controlled: something other than a trigger opens it, like a row's action.
 * The footer's nodes close it through `onOpenChange`'s state. The submit
 * button sits outside the form, in the footer: `form` connects them, and a
 * valid submit closes the dialog.
 */
const InviteSpeaker = () => {
  const [open, setOpen] = useState(false);
  const { control, handleSubmit, reset } = useForm<{ email: string }>({
    defaultValues: { email: '' },
  });

  const invite = handleSubmit(() => {
    reset();
    setOpen(false);
  });

  return (
    <>
      <Button variant="base" onClick={() => setOpen(true)}>
        Invite a speaker
      </Button>
      <Dialog
        title="Invite a speaker"
        open={open}
        onOpenChange={setOpen}
        footer={
          <>
            <Button variant="base" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button type="submit" form="invite-speaker">
              Send invite
            </Button>
          </>
        }
      >
        <Form id="invite-speaker" onSubmit={invite} fill>
          <Controller
            name="email"
            control={control}
            rules={{ required: 'Enter the speaker’s email' }}
          >
            {({ field }) => (
              <Input label="Email" type="email" autoComplete="off" {...field} />
            )}
          </Controller>
        </Form>
      </Dialog>
    </>
  );
};

/**
 * A choice that must be made: `closable={false}` drops the close button,
 * Escape and a press outside, so only the footer closes it.
 */
const CodeOfConduct = () => (
  <Dialog
    title="Code of conduct"
    closable={false}
    trigger={<Button variant="base">Join the event</Button>}
    footer={(close) => (
      <>
        <Button variant="base" onClick={close}>
          Decline
        </Button>
        <Button onClick={close}>I agree</Button>
      </>
    )}
  >
    Be kind, and report harassment to the event staff.
  </Dialog>
);

/**
 * A long body scrolls between the fixed header and footer; `size="lg"` gives
 * a wide one room. `rightAddOn` follows the title, here a session count.
 * `headerAction` is the dialog's own action, before the close button.
 */
const FullAgenda = () => (
  <Dialog
    title="Day one agenda"
    rightAddOn={<Tag size="xs">{agenda.length}</Tag>}
    headerAction={
      <Button size="sm" variant="base">
        Add session
      </Button>
    }
    size="lg"
    trigger={<Button variant="base">See the agenda</Button>}
    footer={(close) => <Button onClick={close}>Done</Button>}
  >
    <ul className="flex-col-gap-2">
      {agenda.map((slot) => (
        <li key={slot}>{slot}</li>
      ))}
    </ul>
  </Dialog>
);

/**
 * Asked and awaited in a handler: each button sends its result, and only a
 * confirm goes ahead. `status="error"` marks a choice that destroys.
 */
const DeleteSession = () => {
  const [deleted, setDeleted] = useState(false);

  const deleteSession = async () => {
    const result = await openConfirmationDialog({
      title: 'Delete this session?',
      content: 'Its 120 attendees lose their seats.',
      status: 'error',
      footer: (closeDialog) => (
        <>
          <Button
            variant="base"
            onClick={() => closeDialog(DialogResult.cancel)}
          >
            Keep it
          </Button>
          <Button
            variant="danger"
            onClick={() => closeDialog(DialogResult.confirm)}
          >
            Delete
          </Button>
        </>
      ),
    });
    if (result === DialogResult.confirm) setDeleted(true);
  };

  return deleted ? (
    <p>Session deleted.</p>
  ) : (
    <Button variant="danger" onClick={deleteSession}>
      Delete session
    </Button>
  );
};

/**
 * From code outside any component, like a router guard: no hook, provider
 * or mounted component. Without `status`, it's a warning.
 */
const confirmLeave = () =>
  openConfirmationDialog({
    title: 'Leave without saving?',
    content: 'Your changes to the agenda are lost.',
    footer: (closeDialog) => (
      <>
        <Button variant="base" onClick={() => closeDialog(DialogResult.cancel)}>
          Stay
        </Button>
        <Button onClick={() => closeDialog(DialogResult.confirm)}>Leave</Button>
      </>
    ),
  });

const LeaveEditor = () => {
  const [left, setLeft] = useState(false);
  return left ? (
    <p>Left the editor.</p>
  ) : (
    <Button
      variant="base"
      onClick={async () =>
        setLeft((await confirmLeave()) === DialogResult.confirm)
      }
    >
      Leave the editor
    </Button>
  );
};

export default function DialogRecipe() {
  return (
    <div className="flex-row-gap-3 flex-wrap">
      <EditSession />
      <InviteSpeaker />
      <CodeOfConduct />
      <FullAgenda />
      <DeleteSession />
      <LeaveEditor />
    </div>
  );
}

