// packages/ui/src/Chip/Chip.recipe.tsx
// Covers: Chip, ChipGroup

/**
 * Chip: a compact toggle showing whether it's on, for filters and quick choices
 * that stay visible. A ChipGroup holds 2 to about 8: one choice
 * (`mode="single"`, the default, read as radio buttons) or any number
 * (`mode="multiple"`, read as checkboxes). One chip on its own is an
 * independent on/off filter.
 *
 * When not to use:
 * - A chosen value the user removes ("Region: Europe"): Tag with `closable`.
 * - An action (save, delete, open a menu): Button.
 * - More than about 8 options, or long labels: Select, or MultiSelect.
 * - A yes/no answer in a form, with a label: Checkbox.
 *
 * Pitfalls:
 * - A ChipGroup needs a name: `label`, `aria-labelledby` pointing at a visible
 *   heading, or `aria-label` when nothing visible asks the question.
 * - In a form, a ChipGroup is the field: spread Controller's `{...field}` on
 *   it. It brings its own label, help text and error; don't wrap it in a
 *   FormControl.
 * - `mode` defaults to single. Set `mode="multiple"` for several at once.
 * - Every chip in a group needs a `value`.
 * - In a group, the mode picks the look (outline for single, filled for
 *   multiple); `look` on its chips can't override it.
 * - A bare count in a chip means nothing read aloud: give it a unit in visually
 *   hidden text ("12 tickets").
 * - `look="collapsed"` on a ChipGroup lays its chips out as one bar that
 *   doesn't wrap: keep it to a few short labels, and give it no layout
 *   `className`.
 * - Say why a chip can't be changed: `disabledWithReason`,
 *   `readOnlyWithReason`, not a bare `disabled`. A ChipGroup takes
 *   `disabledWithReason` too.
 */
import { Button } from '@packages/ui/Button';
import { Chip, ChipGroup } from '@packages/ui/Chip';
import { Controller, Form } from '@packages/ui/Form';
import { Star, Ticket } from 'lucide-react';
import React, { useId, useState } from 'react';
import { useForm } from 'react-hook-form';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const ranges = [
  { value: '7d', label: '7 days' },
  { value: '30d', label: '30 days' },
  { value: '90d', label: '90 days' },
];

const statuses = ['Draft', 'Published', 'Sold out', 'Cancelled'];

const tracks = ['Design', 'Engineering', 'Product', 'Research'];

// Stands in for a request to a server.
const saveInterests = (interests: Interests) =>
  new Promise((resolve) => setTimeout(resolve, 400, interests));

// Usage: the patterns to copy.
/**
 * Single choice: exactly one option is on, like a radio group (a date range, a
 * view mode). Picking one turns the other off. A visible heading names the
 * group via `aria-labelledby`. `look="collapsed"` joins the chips into one
 * bar.
 */
const SingleChoice = () => {
  const [range, setRange] = useState('30d');
  const headingId = useId();

  return (
    <div className="flex-col-gap-2">
      <h3 id={headingId}>Show events from the last</h3>
      <ChipGroup
        mode="single"
        aria-labelledby={headingId}
        value={range}
        onChange={setRange}
        look="collapsed"
      >
        {ranges.map(({ value, label }) => (
          <Chip key={value} value={value}>
            {label}
          </Chip>
        ))}
      </ChipGroup>
    </div>
  );
};

/**
 * Multiple choice: any number of options on, like checkboxes (status
 * filters). With no heading to point at, `aria-label` names the group.
 */
const MultipleChoice = () => {
  const [selected, setSelected] = useState<string[]>(['Published']);

  return (
    <ChipGroup
      mode="multiple"
      aria-label="Event status"
      value={selected}
      onChange={setSelected}
      className="flex-row-gap-2 flex-wrap"
    >
      {statuses.map((status) => (
        <Chip key={status} value={status}>
          {status}
        </Chip>
      ))}
    </ChipGroup>
  );
};

/**
 * Independent toggle: one chip on its own, on or off (a "Starred only" filter),
 * controlled with `active` and `onActiveChange`. `leftIcon` is decoration: the
 * text names it.
 */
const IndependentToggle = () => {
  const [starredOnly, setStarredOnly] = useState(false);

  return (
    <Chip
      leftIcon={<Star />}
      active={starredOnly}
      onActiveChange={setStarredOnly}
    >
      Starred only
    </Chip>
  );
};

/**
 * Starts on: begin the state as `true`. `tooltip` adds detail on hover and
 * focus.
 */
const StartsOn = () => {
  const [available, setAvailable] = useState(true);

  return (
    <Chip
      active={available}
      onActiveChange={setAvailable}
      tooltip="Events with at least one ticket left"
      rightIcon={<Ticket />}
    >
      Tickets available
    </Chip>
  );
};

/**
 * Count after the label: `rightAddOn` takes an element. Screen readers get the
 * count with its unit from hidden text, and skip the visual number.
 */
const WithCount = () => {
  const [paid, setPaid] = useState(true);

  return (
    <Chip
      active={paid}
      onActiveChange={setPaid}
      rightAddOn={<span aria-hidden>12</span>}
    >
      Paid tickets
      <span className="sr-only"> (12 tickets)</span>
    </Chip>
  );
};

/**
 * States: `disabledWithReason`, `readOnlyWithReason` and `loadingWithReason`
 * say why on hover and to screen readers. Loading chips stay put and can't be
 * pressed until done.
 */
const States = () => {
  const [on, setOn] = useState(true);

  return (
    <div className="flex-row-gap-2 flex-wrap">
      <Chip
        active={on}
        onActiveChange={setOn}
        disabledWithReason="Early bird sales have ended"
      >
        Early bird
      </Chip>
      <Chip
        active={on}
        onActiveChange={setOn}
        readOnlyWithReason="Set by the organizer"
      >
        Featured
      </Chip>
      <Chip loadingWithReason="Updating the attendee list">Checked in</Chip>
    </div>
  );
};

/**
 * A disabled group: `disabledWithReason` on the ChipGroup disables every chip
 * and gives each the reason; a chip's own reason wins. `disabled` disables the
 * group silently.
 */
const DisabledGroup = () => {
  const [ticket, setTicket] = useState('general');

  return (
    <ChipGroup
      disabledWithReason="Ticket type is fixed after checkout"
      aria-label="Ticket type"
      value={ticket}
      onChange={setTicket}
      className="flex-row-gap-2 flex-wrap"
    >
      <Chip value="general">General</Chip>
      <Chip value="vip">VIP</Chip>
      <Chip value="speaker" disabledWithReason="Speakers are invited">
        Speaker
      </Chip>
    </ChipGroup>
  );
};

type Interests = { tracks: string[] };

/**
 * In a form: the ChipGroup is the field, rendered through Controller with
 * `{...field}`. `label` names it, `helpText` says what's asked, and the rule's
 * message shows as its error on a failed submit.
 */
const InterestsForm = () => {
  const [status, setStatus] = useState('');
  const { control, handleSubmit } = useForm<Interests>({
    defaultValues: { tracks: [] },
  });

  const submit = async (interests: Interests) => {
    await saveInterests(interests);
    setStatus(`Saved ${interests.tracks.join(', ')}`);
  };

  return (
    <Form
      onSubmit={handleSubmit(submit)}
      actions={<Button type="submit">Save</Button>}
    >
      <Controller
        name="tracks"
        control={control}
        rules={{
          validate: (value) => value.length > 0 || 'Pick at least one track',
        }}
      >
        {({ field }) => (
          <ChipGroup
            mode="multiple"
            label="Tracks"
            helpText="We'll suggest sessions from these."
            {...field}
            className="flex-row-gap-2 flex-wrap"
          >
            {tracks.map((track) => (
              <Chip key={track} value={track}>
                {track}
              </Chip>
            ))}
          </ChipGroup>
        )}
      </Controller>
      <p role="status">{status}</p>
    </Form>
  );
};

export default function ChipRecipe() {
  return (
    <div className="flex-col-gap-6">
      <SingleChoice />
      <MultipleChoice />
      <IndependentToggle />
      <StartsOn />
      <WithCount />
      <States />
      <DisabledGroup />
      <InterestsForm />
    </div>
  );
}

// packages/ui/src/Tag/Tag.recipe.tsx
// Covers: Tag

/**
 * Tag: a short label that only informs: a status, a category, a count, or a
 * chosen filter the user removes with its close button (`closable`). The
 * label stays on one line; cut text shows in full on hover.
 *
 * When not to use:
 * - Anything the user clicks to turn on or off: Chip. A Tag is never pressed.
 * - An action: Button.
 * - Choosing from a list of options: Select, or ChipGroup for a few.
 *
 * Pitfalls:
 * - Removing a tag removes the button that had focus. Keep each close button
 *   in a ref (`closeRef`) and move focus to the next tag's before removing.
 * - A closable tag's `tooltip` shows on its close button, on hover and
 *   focus. On a tag that can't close, it shows on hover only, so put nothing
 *   the user must know there.
 * - A bare count means nothing read aloud: give it a unit, in visually
 *   hidden text if the visible one is dropped.
 * - `closeTabIndex={-1}` is only for a widget that moves focus between its
 *   tags itself, like a toolbar with arrow keys. Otherwise every close
 *   button must stay reachable by Tab.
 * - Say why a tag can't be removed: `disabledWithReason`, not `disabled`.
 */
import { Button } from '@packages/ui/Button';
import { Tag } from '@packages/ui/Tag';
import { CircleCheck, MapPin } from 'lucide-react';
import React, { useRef, useState } from 'react';

// Usage: the patterns to copy.
/** Status: a status variant, `size="xs"` in table rows and dense lists. */
const Status = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Tag size="xs" variant="success" leftIcon={<CircleCheck />}>
      Paid
    </Tag>
    <Tag size="xs" variant="warning">
      Pending
    </Tag>
    <Tag size="xs" variant="error">
      Refunded
    </Tag>
    <Tag size="xs" variant="info">
      Waitlist
    </Tag>
  </div>
);

/**
 * Chosen filters: `closable` with `onClose` removes one. Its close button is
 * read as "Remove" and the label, and `closeRef` lets the caller move focus
 * to the next tag's button (or to "Reset filters" after the last) before the
 * removed one disappears. `disabledWithReason` keeps one that can't be
 * removed and says why on hover and focus.
 */
const ChosenFilters = () => {
  const [teams, setTeams] = useState(['Design', 'Engineering', 'Sales']);
  const closeButtons = useRef(new Map<string, HTMLButtonElement>());
  const resetRef = useRef<HTMLButtonElement>(null);

  const remove = (index: number) => {
    const neighbor = teams[index + 1] ?? teams[index - 1];
    const next = neighbor && closeButtons.current.get(neighbor);

    (next || resetRef.current)?.focus();
    setTeams((current) => current.filter((_, i) => i !== index));
  };

  return (
    <div className="flex-col-gap-2 items-start">
      <ul aria-label="Chosen teams" className="flex-row-gap-2 flex-wrap">
        <li>
          <Tag closable disabledWithReason="Set by your workspace">
            Region: Europe
          </Tag>
        </li>
        {teams.map((team, index) => (
          <li key={team}>
            <Tag
              closable
              closeRef={(node) => {
                if (node) closeButtons.current.set(team, node);
                return () => {
                  closeButtons.current.delete(team);
                };
              }}
              onClose={() => remove(index)}
            >
              {team}
            </Tag>
          </li>
        ))}
      </ul>
      <Button
        ref={resetRef}
        variant="base"
        look="ghost"
        onClick={() => setTeams([])}
      >
        Reset filters
      </Button>
    </div>
  );
};

/**
 * Icon and count: `rightIcon` follows the label, and `leftAddOn` takes an
 * element before it. The unit is in visually hidden text, so the number is
 * read with its meaning and the visible number is skipped.
 */
const IconsAndCount = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Tag rightIcon={<MapPin />}>Berlin</Tag>
    <Tag variant="default" leftAddOn={<span aria-hidden>12</span>}>
      Engineering
      <span className="sr-only"> (12 events)</span>
    </Tag>
  </div>
);

/**
 * Tooltip: more detail on hover. A tag that can't close takes no focus, so
 * keyboard and touch users never see it: only extra detail goes there. On a
 * closable tag the tooltip moves to the close button and shows on focus too.
 */
const WithTooltip = () => (
  <Tag variant="warning" tooltip="Fewer than 10 tickets left">
    Almost full
  </Tag>
);

export default function TagRecipe() {
  return (
    <div className="flex-col-gap-6">
      <Status />
      <ChosenFilters />
      <IconsAndCount />
      <WithTooltip />
    </div>
  );
}

// packages/ui/src/Toast/Toast.recipe.tsx
// Covers: dismissToast, toast, updateToast

/**
 * toast: a short message at the corner of the screen about something that
 * just happened, like "Session saved", that closes on its own. Call it from
 * anywhere, React or not: it returns the toast's id. updateToast changes a
 * showing toast, dismissToast closes one, clearToasts closes all.
 *
 * When not to use:
 * - An error the user must fix in a form: the field's `error`.
 * - A question that needs an answer: openConfirmationDialog.
 * - Something that must stay on screen, like a sold-out notice: text on the
 *   page itself.
 *
 * Pitfalls:
 * - UIRoot renders the toasts: without it, a toast shows nowhere.
 * - The title is one line and truncates: put details in `description`.
 * - An `action` needs `altText`: how to do the same without the toast, as a
 *   screen reader may hear the toast after it has gone.
 * - A `loading` toast stays until updateToast or dismissToast: always end it.
 * - updateToast and dismissToast do nothing for an unknown or closed id, and
 *   `onClose` runs once, however the toast closes.
 */
import { Button } from '@packages/ui/Button';
import {
  clearToasts,
  dismissToast,
  toast,
  updateToast,
} from '@packages/ui/Toast';
import React, { useState } from 'react';

// Setup: stand-ins for your app's requests, not part of the pattern.
const publishSchedule = (fail: boolean) =>
  new Promise<void>((resolve, reject) => {
    setTimeout(() => (fail ? reject(new Error('Offline')) : resolve()), 800);
  });

// Usage: the patterns to copy.
/** After an action: `status` sets the icon; `info` without it. */
const SaveSession = () => (
  <Button
    onClick={() =>
      toast({
        title: 'Session saved',
        description: 'Attendees see the new time at once.',
        status: 'success',
      })
    }
  >
    Save session
  </Button>
);

/**
 * A request in flight: a `loading` toast that updateToast turns into the
 * outcome, which then closes on its own.
 */
const PublishSchedule = ({ fail = false }: { fail?: boolean }) => (
  <Button
    variant="base"
    onClick={async () => {
      const id = toast({ title: 'Publishing the schedule', status: 'loading' });
      try {
        await publishSchedule(fail);
        updateToast(id, { title: 'Schedule published', status: 'success' });
      } catch {
        updateToast(id, {
          title: 'Couldn’t publish the schedule',
          description: 'Check your connection and try again.',
          status: 'error',
        });
      }
    }}
  >
    {fail ? 'Publish, offline' : 'Publish schedule'}
  </Button>
);

/**
 * An action that undoes what just happened. `altText` tells screen readers
 * where else to do it; pressing the action closes the toast.
 */
const RemoveSpeaker = () => {
  const [removed, setRemoved] = useState(false);

  const remove = () => {
    setRemoved(true);
    toast({
      title: 'Speaker removed',
      action: {
        label: 'Undo',
        altText: 'Add them back from the speakers list',
        onClick: () => setRemoved(false),
      },
    });
  };

  return (
    <Button variant="base" onClick={remove}>
      {removed ? 'Removed' : 'Remove speaker'}
    </Button>
  );
};

/**
 * A toast that waits for the user: `duration={Infinity}` and a close button.
 * dismissToast closes it from code; `onClose` learns either way.
 */
const ConnectionLost = () => {
  const [id, setId] = useState<string>();

  const show = () =>
    setId(
      toast({
        title: 'Connection lost',
        description: 'Changes are saved once you’re back online.',
        status: 'warning',
        duration: Infinity,
        closable: true,
        onClose: () => setId(undefined),
      }),
    );

  return id ? (
    <Button variant="base" onClick={() => dismissToast(id)}>
      Back online
    </Button>
  ) : (
    <Button variant="base" onClick={show}>
      Go offline
    </Button>
  );
};

/** From code outside any component, like leaving a page: clear them all. */
const leaveEditor = () => clearToasts();

export default function ToastRecipe() {
  return (
    <div className="flex-row-gap-3 flex-wrap">
      <SaveSession />
      <PublishSchedule />
      <PublishSchedule fail />
      <RemoveSpeaker />
      <ConnectionLost />
      <Button variant="base" onClick={leaveEditor}>
        Clear all
      </Button>
    </div>
  );
}

// packages/ui/src/Typography/Typography.recipe.tsx
// Covers: Caption, Code, CodeBlock, DescriptionDetails, DescriptionList, DescriptionTerm, Kbd, List, ListItem, Mark, Paragraph, Quote, Separator, Time

/**
 * Typography: the text elements of a page, styled by the design system:
 * `Paragraph`, `Caption`, `List` with `ListItem`, `DescriptionList` with
 * `DescriptionTerm` and `DescriptionDetails`, `Quote`, `Code`, `CodeBlock`,
 * `Kbd`, `Mark`, `Separator` and `Time`.
 * - `color` (default, muted, primary or a status) replaces the color the
 *   text inherits. Every element but `Separator` takes it.
 * - `font` (ui, display or mono) replaces the font the text inherits.
 *   `Code`, `CodeBlock` and `Kbd` are always mono, and `Separator` has no
 *   text, so these four don't take it.
 * - Size and line height are fixed: the caption's for `Caption`, the
 *   surrounding text's for `Code`, `Kbd`, `Mark` and `Time`, and the body's
 *   for the others.
 *
 * When not to use:
 * - A heading: a `Section`'s title is the heading.
 * - A line between groups: a gap between them is usually enough. Use a
 *   `Separator` only where the groups need a visible line.
 * - A list of records: a `CardList` or a `Table`. A `List` is for text.
 * - Rows people sort, filter or compare across: a `Table`.
 * - A number people read and compare: a `Numeral`, inside the text element.
 *
 * Pitfalls:
 * - Spacing between paragraphs and lists comes from their parent's gap,
 *   such as `flex-col-gap-3`: the elements have no margins.
 * - `ordered` only when the order means something, such as steps.
 * - A `CodeBlock` takes the code as a string: keep its line breaks in a
 *   template literal.
 */
import { Numeral } from '@packages/ui/Numeral';
import {
  Caption,
  Code,
  CodeBlock,
  DescriptionDetails,
  DescriptionList,
  DescriptionTerm,
  Kbd,
  List,
  ListItem,
  Mark,
  Paragraph,
  Quote,
  Separator,
  Time,
} from '@packages/ui/Typography';
import React from 'react';

// Setup: stand-ins for your app's data, not part of the pattern.
const record = [
  { label: 'Created', value: '2 Nov 2026' },
  { label: 'Status', value: 'Active' },
  { label: 'Owner', value: 'Alex Morgan' },
];
const setup = `pnpm install
pnpm dev`;

// Usage: the patterns to copy.
/** Body text: paragraphs in a column, spaced by the parent's gap. */
const Text = () => (
  <div className="flex-col-gap-3">
    <Paragraph>
      A paragraph of body text, which wraps to the width of its column.
    </Paragraph>
    <Paragraph color="muted">A muted paragraph for a detail.</Paragraph>
  </div>
);

/** A small muted line on the text above it, such as when a record was made. */
const Note = () => (
  <div className="flex-col-gap-1">
    <Paragraph>Spring launch plan</Paragraph>
    <Caption>Updated 2 Nov 2026</Caption>
  </div>
);

/** Points in any order, bulleted. An item may hold a list of its own. */
const Points = () => (
  <List>
    <ListItem>First point</ListItem>
    <ListItem>
      Second point
      <List>
        <ListItem>A point under it</ListItem>
      </List>
    </ListItem>
  </List>
);

/** Steps the reader follows in order, numbered. */
const Steps = () => (
  <List ordered>
    <ListItem>Fill in the form</ListItem>
    <ListItem>Check the details</ListItem>
    <ListItem>Confirm</ListItem>
  </List>
);

/** A record's fields as label and value pairs, one pair a row. */
const Fields = () => (
  <DescriptionList>
    {record.map(({ label, value }) => (
      <div key={label}>
        <DescriptionTerm>{label}</DescriptionTerm>
        <DescriptionDetails>{value}</DescriptionDetails>
      </div>
    ))}
    <div>
      <DescriptionTerm>Items</DescriptionTerm>
      <DescriptionDetails>
        <Numeral>1,300</Numeral>
      </DescriptionDetails>
    </div>
  </DescriptionList>
);

/** Someone's words, with who said them. Without `source`, just the quote. */
const Testimonial = () => (
  <Quote source="Alex Morgan" font="display">
    Someone's words, as they said them.
  </Quote>
);

/** Code in a sentence, and lines of code on their own. */
const Commands = () => (
  <div className="flex-col-gap-3">
    <Paragraph>
      Start the app with <Code>pnpm dev</Code> once the packages are in.
    </Paragraph>
    <CodeBlock>{setup}</CodeBlock>
  </div>
);

/** A shortcut named in a sentence. */
const Shortcut = () => (
  <Paragraph>
    Press <Kbd>Ctrl K</Kbd> to search.
  </Paragraph>
);

/** A search result's line, with the words that match the search marked. */
const SearchResult = () => (
  <Paragraph>
    Spring <Mark>launch</Mark> plan
  </Paragraph>
);

/**
 * A line between two groups of text that need one, and between items in a
 * row, where the row stretches it to its height.
 */
const Groups = () => (
  <div className="flex-col-gap-3">
    <Paragraph>Delivery by courier, in 3 to 5 days.</Paragraph>
    <Separator />
    <div className="flex-row-gap-3">
      <Paragraph>2 items</Paragraph>
      <Separator orientation="vertical" />
      <Paragraph>Paid by card</Paragraph>
    </div>
  </div>
);

/**
 * A record's date or moment, from the ISO value it keeps: one format across
 * the app. `withTime` adds the time of day to a moment.
 */
const Dates = () => (
  <Paragraph>
    Placed <Time value="2026-11-07" />, shipped{' '}
    <Time value="2026-11-09T10:30:00.000Z" withTime />.
  </Paragraph>
);

export default function TypographyRecipe() {
  return (
    <div className="flex-col-gap-6">
      <Text />
      <Note />
      <Points />
      <Steps />
      <Fields />
      <Testimonial />
      <Commands />
      <Shortcut />
      <SearchResult />
      <Groups />
      <Dates />
    </div>
  );
}

