// packages/ui/src/Numeral/Numeral.recipe.tsx
// Covers: Numeral

/**
 * Numeral: a number the user reads and compares, such as a count, a total,
 * a statistic or a table's figures. It sets the digits in the theme's mono
 * font, so they line up in a column and a count that changes doesn't move
 * what sits beside it. A currency sign, a unit or words in it keep the text's
 * font. Size, weight and color come from around it.
 *
 * When not to use:
 * - A number inside a sentence ("3 books left to read"): it is part of the
 *   text and stays in the text's font.
 * - A date, a time or a phone number: people read them as text.
 *
 * Pitfalls:
 * - Format the number before you pass it: Numeral only sets its font. Use
 *   `toLocaleString` or `Intl.NumberFormat` for separators and currency.
 * - Keep the label outside: "Pages read" is text, only the figure is a
 *   Numeral. A unit that belongs to the figure, like € or %, goes inside;
 *   Numeral keeps it in the text's font. Never split a figure into a
 *   Numeral for the digits and text for the unit yourself.
 */
import { IconButton } from '@packages/ui/Button';
import { Numeral } from '@packages/ui/Numeral';
import {
  DescriptionDetails,
  DescriptionList,
  DescriptionTerm,
} from '@packages/ui/Typography';
import { Minus, Plus } from 'lucide-react';
import React, { useState } from 'react';

// Setup: stand-ins for your app's data, not part of the pattern.
const totals = [
  { label: 'Groceries', amount: 1249.5 },
  { label: 'Rent', amount: 950 },
  { label: 'Transport', amount: 86.25 },
];
const euros = new Intl.NumberFormat('en-IE', {
  style: 'currency',
  currency: 'EUR',
});

// Usage: the patterns to copy.
/** A count that changes: the buttons beside it stay where they are. */
const Counter = () => {
  const [count, setCount] = useState(9);
  return (
    <div className="flex-row-gap-2 items-center">
      <IconButton tooltip="Decrease" onClick={() => setCount(count - 1)}>
        <Minus />
      </IconButton>
      <Numeral aria-live="polite">{count}</Numeral>
      <IconButton tooltip="Increase" onClick={() => setCount(count + 1)}>
        <Plus />
      </IconButton>
    </div>
  );
};

/** A statistic: the figure takes its size from the element around it. */
const Statistic = () => (
  <div className="flex-col-gap-1">
    <span>Pages read this week</span>
    <span className="text-heading">
      <Numeral>{(1834).toLocaleString('en')}</Numeral>
    </span>
  </div>
);

/** Totals in a column: aligned to the end, the digits line up. */
const Totals = () => (
  <DescriptionList>
    {totals.map(({ label, amount }) => (
      <div key={label}>
        <DescriptionTerm>{label}</DescriptionTerm>
        <DescriptionDetails className="text-right">
          <Numeral>{euros.format(amount)}</Numeral>
        </DescriptionDetails>
      </div>
    ))}
  </DescriptionList>
);

export default function NumeralRecipe() {
  return (
    <div className="flex-col-gap-6 items-start">
      <Counter />
      <Statistic />
      <Totals />
    </div>
  );
}

// packages/ui/src/Section/Section.recipe.tsx
// Covers: Section, SectionGroup, sectionGroup

/**
 * Section: a titled part of a page, like a settings page's "Profile" and
 * "Notifications": a heading, an optional muted description, then the
 * content, with the same sizes and spacing on every page.
 *
 * When not to use:
 * - Content the user opens and closes: Collapsible, or an Accordion for
 *   several.
 * - One item among many, like an event in a gallery: Card.
 * - A label for one field or one group of choices: the field's `label`.
 *
 * Pitfalls:
 * - The heading level comes from nesting: a Section is an `h2`, one inside a
 *   Section an `h3`, and so on. Don't wrap `title` in a heading of your own.
 * - A Section is never the page's H1. A page's H1 is its PageHeader's
 *   title. In `web/app/(routes)/(marketing)/page.tsx`, the page at `/`, it is the Hero's
 *   headline.
 * - `headingAs` picks another level when nesting picks the wrong one.
 *   Sections inside continue from it.
 * - Titles are one size at every level: don't restyle a nested one.
 * - Stack sections in a SectionGroup, which puts a fixed gap between them.
 *   A Section on its own pads itself above and below. A page's sections
 *   need no group: the page spaces them.
 * - A Section has no side padding by default, so its heading lines up with
 *   the PageHeader and the text around it. The sides come from what wraps
 *   it: the page's container, a Card or a panel. Where one section needs
 *   sides of its own, give them with `className`, such as `px-4`.
 * - `description` is one muted line about the section; anything longer, or
 *   anything to act on, goes in the content.
 * - `headerAction` holds the section's own actions, like Add, at the
 *   header's end. Actions on one item in the content stay with that item.
 * - `leftIcon` and `rightIcon` are decoration. `leftAddOn` and `rightAddOn`,
 *   like a Tag, are read as part of the heading: no buttons or links.
 */
import { Button } from '@packages/ui/Button';
import { Card } from '@packages/ui/Card';
import { Input } from '@packages/ui/Input';
import { Section, SectionGroup } from '@packages/ui/Section';
import { Switch } from '@packages/ui/Switch';
import { Tag } from '@packages/ui/Tag';
import { Paragraph } from '@packages/ui/Typography';
import { Bell, User } from 'lucide-react';
import React, { useState } from 'react';

// Usage: the patterns to copy.
/**
 * Sections stacked in a SectionGroup: each with its heading and description,
 * then its content; the last has no description. An icon marks a heading; a
 * Tag after it (`rightAddOn`) shows a state.
 */
const SettingsSections = () => {
  const [name, setName] = useState('Ada Lovelace');
  const [reminders, setReminders] = useState(true);

  return (
    <SectionGroup>
      <Section
        title="Profile"
        description="How other attendees see you"
        leftIcon={<User />}
      >
        <Input
          label="Display name"
          autoComplete="name"
          value={name}
          onChange={setName}
        />
      </Section>
      <Section
        title="Notifications"
        description="What we send before your sessions"
        leftIcon={<Bell />}
        rightAddOn={<Tag>{reminders ? 'On' : 'Off'}</Tag>}
      >
        <Switch checked={reminders} onCheckedChange={setReminders}>
          Remind me an hour before
        </Switch>
      </Section>
      <Section title="Danger zone">
        <div>
          <Button variant="danger">Delete account</Button>
        </div>
      </Section>
    </SectionGroup>
  );
};

/**
 * Sections inside a section take the next heading level, `h3` here, at the
 * same size, so the outline stays right without any level to pass. The
 * section's own action goes in `headerAction`.
 */
const NestedSections = () => (
  <Section
    title="Venue"
    description="Where the sessions happen"
    headerAction={<Button variant="base">Add hall</Button>}
  >
    <Section title="Hall A">
      <p>Second floor, 300 seats.</p>
    </Section>
    <Section title="Hall B">
      <p>Ground floor, 120 seats.</p>
    </Section>
  </Section>
);

/**
 * The wrapper gives the sides: a Card's padding here, the page's container
 * on a page. A plain heading, a paragraph and the sections all start on its
 * one left edge.
 */
const SharedLeftEdge = () => (
  <Card>
    <h2 className="font-display text-heading font-heading">
      Frontend summit
    </h2>
    <Paragraph>Two days of talks on the web platform, in Lisbon.</Paragraph>
    <SectionGroup>
      <Section title="Hall A" description="Second floor">
        <Paragraph>300 seats, with a stage and two screens.</Paragraph>
      </Section>
      <Section title="Hall B" description="Ground floor">
        <Paragraph>120 seats, for the workshops.</Paragraph>
      </Section>
    </SectionGroup>
  </Card>
);

export default function SectionRecipe() {
  return (
    <div className="flex-col-gap-8">
      <SettingsSections />
      <NestedSections />
      <SharedLeftEdge />
    </div>
  );
}

// packages/ui/src/Image/Image.recipe.tsx
// Covers: Image

/**
 * Image: a picture in a box of a set width and height, such as a product
 * photo, a cover or a logo. The box narrows with its parent and keeps its
 * ratio, so the page doesn't jump while the picture loads. A missing or
 * broken picture leaves the box in place, with an icon in the middle: an
 * image icon, or the `fallbackIcon` you give.
 *
 * When not to use:
 * - A person's picture or initials: Avatar.
 * - An icon: a lucide-react icon.
 * - A band of color or a gradient: a background from the theme's tokens.
 *
 * Pitfalls:
 * - `width` and `height` are the box at full width. Give the picture's own
 *   ratio; in a narrower parent the box narrows and keeps it.
 * - Give one side only when the picture's shape is unknown, such as one a
 *   user uploads: its own ratio sets the other side once it loads, and
 *   without a picture the box is square.
 * - `alt` says what the picture shows. Use "" only for a picture that
 *   decorates, such as the backdrop behind a headline.
 * - Text over a picture sits on a surface of its own, such as a Card, so it
 *   stays readable on any picture.
 * - Leave `src` out when a record has no picture yet: the box keeps its place.
 * - `fallbackIcon` is one lucide-react icon. The box sets its size and color.
 */
import { Card } from '@packages/ui/Card';
import { Image } from '@packages/ui/Image';
import { Paragraph } from '@packages/ui/Typography';
import { Package } from 'lucide-react';
import React from 'react';

// Setup: stand-ins for your app's data, not part of the pattern.
const picture = (width: number, height: number, from: string, to: string) =>
  `data:image/svg+xml,${encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><linearGradient id="g"><stop offset="0" stop-color="${from}"/><stop offset="1" stop-color="${to}"/></linearGradient><rect width="100%" height="100%" fill="url(#g)"/></svg>`,
  )}`;
const photo = picture(400, 300, '#475569', '#CBD5E1');
const logo = picture(200, 60, '#334155', '#94A3B8');
const backdrop = picture(1200, 400, '#1E293B', '#64748B');

// Usage: the patterns to copy.
/** A photo that fills its box: `cover` crops what does not fit. */
const Photo = () => (
  <Image
    src={photo}
    alt="What the photo shows"
    width={400}
    height={300}
    fit="cover"
  />
);

/** A logo or a screenshot shown whole: `contain` leaves room around it. */
const Logo = () => (
  <Image
    src={logo}
    alt="The company's name"
    width={240}
    height={120}
    fit="contain"
  />
);

/** A picture of unknown shape: its width only; its own ratio sets the height. */
const UnknownShape = () => (
  <Image src={photo} alt="What the photo shows" width={240} fit="cover" />
);

/** A record with no picture yet: the box keeps its place with an icon. */
const NoPicture = () => (
  <Image alt="The record's name" width={400} height={300} fit="cover" />
);

/** A record with no picture yet, shown by the icon of its kind: `fallbackIcon`. */
const NoPictureWithIcon = () => (
  <Image
    alt="The item's name"
    width={400}
    height={300}
    fit="cover"
    fallbackIcon={<Package />}
  />
);

/** A backdrop with content over it: the picture becomes the box's background. */
const Backdrop = () => (
  <Image
    src={backdrop}
    alt=""
    width={1200}
    height={400}
    fit="cover"
    className="flex-row-gap-0 items-center justify-center p-6"
  >
    <Card>
      <Paragraph>A headline over the picture.</Paragraph>
    </Card>
  </Image>
);

export default function ImageRecipe() {
  return (
    <div className="flex-col-gap-6">
      <Photo />
      <Logo />
      <UnknownShape />
      <NoPicture />
      <NoPictureWithIcon />
      <Backdrop />
    </div>
  );
}

// packages/ui/src/Button/Button.recipe.tsx
// Covers: Button, IconButton, PlainButton

/**
 * Button: an action the user takes: save, publish, delete, open a menu.
 * `default` is the main action of a view (one per view), `base` a secondary
 * one, `danger` one that deletes or can't be undone: filled, it is the
 * confirm dialog's button, and on a list row a delete is as quiet as the
 * row's other actions. `look="ghost"` makes any of them quiet, for toolbars
 * and rows, where an action is an IconButton with a tooltip. IconButton is
 * an action shown as an icon alone; PlainButton makes a non-button element,
 * like an info icon or an avatar, act as a button.
 *
 * When not to use:
 * - Going to another page: Link. In the Next app, a route is the app's
 *   NextLink, and one that must look like a button is
 *   `Button as={NextLink}`.
 * - A toggle that shows whether it's on: Chip.
 * - Two `default` buttons in one view: make the lesser one `base`.
 *
 * Pitfalls:
 * - `type` defaults to "button". A form's submit needs `type="submit"`.
 * - Deleting a row removes the button that had focus: move focus on, to a
 *   stable button, with a `ref`.
 * - IconButton needs a `tooltip`; a string one is its accessible name. Add
 *   `aria-label` or `aria-labelledby` only when the name must differ from
 *   what the tooltip shows, like "Delete Design review" under "Delete".
 * - Say why a button can't be used: `disabledWithReason`,
 *   `readOnlyWithReason`, `loadingWithReason`. A bare `disabled` leaves the
 *   user guessing.
 */
import { Avatar } from '@packages/ui/Avatar';
import { Button, IconButton, PlainButton } from '@packages/ui/Button';
import { Controller, Form } from '@packages/ui/Form';
import { Input } from '@packages/ui/Input';
import { Copy, Info, Play, Plus, Settings, Trash2 } from 'lucide-react';
import React, { useEffect, useId, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
const saveEvent = (draft: EventDraft) =>
  new Promise<EventDraft>((resolve) => setTimeout(() => resolve(draft), 800));

// Usage: the patterns to copy.
type EventDraft = { title: string };

/**
 * Saving a form: `type="submit"` makes the button send the form, and
 * `loading` follows `formState.isSubmitting`, so it can't be pressed twice.
 * The result is announced through a status region.
 */
const SaveForm = () => {
  const [saved, setSaved] = useState('');
  const { control, handleSubmit, reset, formState } = useForm<EventDraft>({
    defaultValues: { title: '' },
  });

  return (
    <Form
      onSubmit={handleSubmit(async (draft) => {
        const result = await saveEvent(draft);
        setSaved(`Saved "${result.title}"`);
      })}
      actions={
        <>
          <Button variant="base" onClick={() => reset()}>
            Reset
          </Button>
          <Button
            type="submit"
            // Saving takes a moment and the status above reports the result.
            loading={formState.isSubmitting}
          >
            Save
          </Button>
        </>
      }
    >
      <Controller
        name="title"
        control={control}
        rules={{ required: 'Enter the event title' }}
      >
        {({ field }) => (
          <Input label="Event title" autoComplete="off" {...field} />
        )}
      </Controller>
      <p role="status">{saved}</p>
    </Form>
  );
};

/** A form's actions: the main one last, the secondary one `base`. */
const FormActions = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button variant="base">Cancel</Button>
    <Button>Publish</Button>
  </div>
);

/**
 * Icons: `leftIcon` before the label, `rightIcon` after it. Icons are
 * decoration; the text names the button.
 */
const WithIcons = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button leftIcon={<Plus />}>New event</Button>
    <Button variant="base" rightIcon={<Play />}>
      Start session
    </Button>
  </div>
);

/**
 * A key hint: `rightAddOn` takes an element, hidden from screen readers
 * because `aria-keyshortcuts` announces the key. The shortcut itself must
 * work, so a key listener runs the action.
 */
const WithShortcut = () => {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement;
      if (event.key !== 'n' || event.ctrlKey || event.metaKey) return;
      if (target.closest('input, textarea, [contenteditable]')) return;
      setCount((current) => current + 1);
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);

  return (
    <div className="flex-col-gap-2 items-start">
      <Button
        aria-keyshortcuts="N"
        rightAddOn={<kbd aria-hidden>N</kbd>}
        onClick={() => setCount((current) => current + 1)}
      >
        New event
      </Button>
      <p role="status">Events created: {count}</p>
    </div>
  );
};

/**
 * Tooltip: detail on hover and focus, read as the description. With a
 * disabled reason, both show, the tooltip first.
 */
const WithTooltip = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button tooltip="Sends the event to every subscriber">Publish</Button>
    <Button
      tooltip="Sends the event to every subscriber"
      disabledWithReason="Add a date before publishing"
    >
      Publish
    </Button>
  </div>
);

/**
 * Unavailable: `disabledWithReason` disables it and says why. Read-only
 * (`readOnlyWithReason`) keeps the button visible but inert, for a view the
 * user may not change.
 */
const Unavailable = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button disabledWithReason="Add a date before publishing">Publish</Button>
    <Button readOnlyWithReason="Only organizers can edit the schedule">
      Edit schedule
    </Button>
    <Button
      // The page shows no draft yet, so the reason is plain.
      disabled
    >
      Discard draft
    </Button>
  </div>
);

/**
 * Busy: `loading` shows a spinner in place of the icon and the button can't
 * be pressed again until it's done. `loadingWithReason` also says what is
 * happening, to sighted users on hover and in a status region for screen
 * readers. Set one of the two, not both.
 */
const Busy = () => {
  const [syncing, setSyncing] = useState(false);

  return (
    <div className="flex-row-gap-2 flex-wrap">
      <Button
        loadingWithReason={syncing ? 'Syncing the attendee list' : undefined}
        onClick={() => {
          setSyncing(true);
          setTimeout(() => setSyncing(false), 1500);
        }}
      >
        Sync attendees
      </Button>
      <Button loadingWithReason="Exporting the guest list">
        Export guests
      </Button>
    </div>
  );
};

/**
 * Play and stop in one button: `disableWhileLoading={false}` keeps it
 * pressable while loading, so the press that started it can stop it.
 */
const RunAndStop = () => {
  const [running, setRunning] = useState(false);

  return (
    <Button
      leftIcon={<Play />}
      // It stays pressable, and the label changes to Stop.
      loading={running}
      disableWhileLoading={false}
      onClick={() => setRunning(!running)}
    >
      {running ? 'Stop' : 'Run'}
    </Button>
  );
};

/**
 * Keeping focus after a delete: the removed row's button disappears, so a
 * `ref` on a stable button moves focus there.
 */
const DeleteRow = () => {
  const [sessions, setSessions] = useState(['Opening keynote', 'Workshop']);
  const addRef = useRef<HTMLButtonElement>(null);

  return (
    <div className="flex-col-gap-2 items-start">
      <ul aria-label="Sessions" className="flex-col-gap-2">
        {sessions.map((session) => (
          <li key={session} className="flex-row-gap-2 items-center">
            {session}
            <IconButton
              variant="danger"
              look="ghost"
              tooltip="Delete"
              aria-label={`Delete ${session}`}
              onClick={() => {
                addRef.current?.focus();
                setSessions((current) =>
                  current.filter((entry) => entry !== session),
                );
              }}
            >
              <Trash2 />
            </IconButton>
          </li>
        ))}
      </ul>
      <Button
        ref={addRef}
        leftIcon={<Plus />}
        onClick={() => setSessions((current) => [...current, 'New session'])}
      >
        Add session
      </Button>
    </div>
  );
};

/**
 * Icon only: IconButton, named by its `tooltip`, which shows on hover and
 * focus. Sizes `xs`, `sm` (the default) and `md`. `loading` and
 * `disabledWithReason` work as on Button.
 */
const IconOnly = () => (
  <div className="flex-row-gap-2 flex-wrap items-center">
    <IconButton variant="base" look="ghost" size="xs" tooltip="Event settings">
      <Settings />
    </IconButton>
    <IconButton variant="base" tooltip="Event settings">
      <Settings />
    </IconButton>
    <IconButton size="md" variant="danger" tooltip="Delete event">
      <Trash2 />
    </IconButton>
    <IconButton loadingWithReason="Duplicating event" tooltip="Duplicate event">
      <Copy />
    </IconButton>
    <IconButton
      disabledWithReason="Cancelled events can't be copied"
      tooltip="Duplicate event"
    >
      <Copy />
    </IconButton>
  </div>
);

/**
 * A name that differs from the tooltip: `aria-labelledby` points at visible
 * text, here the row's title, and `aria-label` gives a fuller name, like
 * "Duplicate Design review" under the tooltip "Duplicate".
 */
const IconNames = () => {
  const titleId = useId();

  return (
    <div className="flex-row-gap-2 items-center">
      <span id={titleId}>Design review</span>
      <IconButton aria-labelledby={titleId} tooltip="Settings">
        <Settings />
      </IconButton>
      <IconButton aria-label="Duplicate Design review" tooltip="Duplicate">
        <Copy />
      </IconButton>
    </div>
  );
};

/**
 * An info icon that shows details below it: PlainButton makes its one child,
 * a non-interactive element, focusable and pressable by Enter and Space, with
 * the look the child already has, its focus style included. Name it with
 * `aria-label`; `aria-expanded` and `aria-controls` say what it opens. For a
 * styled action use IconButton.
 */
const InfoIcon = () => {
  const [open, setOpen] = useState(false);
  const detailsId = useId();

  return (
    <div className="flex-col-gap-2 items-start">
      <PlainButton
        aria-label="About ticket types"
        aria-expanded={open}
        aria-controls={detailsId}
        onClick={() => setOpen(!open)}
      >
        <span>
          <Info aria-hidden />
        </span>
      </PlainButton>
      <p id={detailsId} hidden={!open}>
        VIP includes the speaker dinner.
      </p>
    </div>
  );
};

/**
 * An avatar that does something when pressed, like showing a person's
 * details. Avatar hides itself from assistive tech, so the `span` around it
 * is the button, and `aria-label` names it.
 */
const OrganizerAvatar = () => {
  const [contact, setContact] = useState('');

  return (
    <div className="flex-row-gap-2 items-center">
      <PlainButton
        aria-label="Show contact details for Grace Hopper"
        onClick={() => setContact('Grace Hopper, grace@example.com')}
      >
        <span>
          <Avatar name="Grace Hopper" />
        </span>
      </PlainButton>
      <p role="status">{contact}</p>
    </div>
  );
};

export default function ButtonRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <SaveForm />
      <FormActions />
      <WithIcons />
      <WithShortcut />
      <WithTooltip />
      <Unavailable />
      <Busy />
      <RunAndStop />
      <DeleteRow />
      <IconOnly />
      <IconNames />
      <InfoIcon />
      <OrganizerAvatar />
    </div>
  );
}

