// web/app/components/NotFound/NotFound.recipe.tsx
// Covers: NotFound

/**
 * NotFound: a record's page when its id finds nothing. A title naming what
 * is missing as the page's H1, one line on why, and the way back to the
 * list, the same on every record's page.
 *
 * When not to use:
 * - An empty list: the list's own empty state, with the action that fills it.
 * - A route the app doesn't have: Next's own not-found page.
 *
 * Pitfalls:
 * - It replaces the whole page, PageHeader included: return it alone.
 * - Name the record by its noun in the title, "Order not found", never "Not
 *   found" alone.
 */
import { NotFound } from '@app/components/NotFound';
import React from 'react';

// Usage: the patterns to copy.
/** The page of an order whose id matches none. */
const MissingOrder = () => (
  <NotFound
    title="Order not found"
    description="It may have been deleted, or the link is wrong."
    back={{ label: 'Back to orders', href: '/orders' }}
  />
);

export default function NotFoundRecipe() {
  return <MissingOrder />;
}

// web/app/components/NextLink/NextLink.recipe.tsx
// Covers: NextLink

/**
 * NextLink: a link to a route of this app (`/events/42`). Next.js navigates
 * to it without reloading the page and prefetches it. It looks like Link,
 * which is for other sites, emails, phone numbers and files: a dotted line
 * inside text, `look="plain"` as a control.
 *
 * When not to use:
 * - Another site, an email, a phone number or a file: Link.
 * - An action (save, delete, open a menu): Button. A link goes somewhere.
 * - A whole card that opens a page: Card with `stretchLink`, and a plain
 *   NextLink on its title.
 *
 * Pitfalls:
 * - The dotted line is for a link inside text only. A link that stands on its
 *   own as a control, such as a way back, a breadcrumb or a navigation item,
 *   is `look="plain"`.
 * - A route as Link reloads the whole page: use NextLink.
 * - A route that must look like a button is `Button as={NextLink}`, not a
 *   bare NextLink, whose dotted line clashes with a button.
 * - Mark the current page in a nav with `aria-current="page"`.
 * - Say why a link is disabled: `disabledWithReason` keeps it focusable and
 *   shows the reason on focus; a plain `disabled` link leaves the tab order.
 */
import { NextLink } from '@app/components/NextLink';
import { Button } from '@packages/ui/Button';
import { Input } from '@packages/ui/Input';
import { Plus } from 'lucide-react';
import React, { useState } from 'react';

// Usage: the patterns to copy.
/** In a sentence: it sits inline and wraps with the text around it. */
const InText = () => (
  <p>
    Read the <NextLink href="/guidelines">event guidelines</NextLink> before you
    publish.
  </p>
);

/**
 * Takes `replace`, `scroll`, `prefetch` and `onNavigate`, as Next.js's `Link`
 * does; `scroll={false}` keeps the scroll position.
 */
const KeepScroll = () => (
  <NextLink href="/events/42" scroll={false}>
    Design review
  </NextLink>
);

/**
 * A way back that replaces the current history entry instead of adding
 * another one. It works as a control, so it is `plain`.
 */
const ReplaceHistory = () => (
  <NextLink look="plain" href="/events" replace>
    Back to events
  </NextLink>
);

/**
 * The current page in a navigation: `aria-current="page"` tells screen
 * readers which link they're on. The nav itself is named, and its links are
 * `plain`: they work as controls.
 */
const Navigation = () => (
  <nav aria-label="Event sections">
    <ul className="flex-row-gap-4">
      <li>
        <NextLink look="plain" href="/events/42" aria-current="page">
          Overview
        </NextLink>
      </li>
      <li>
        <NextLink look="plain" href="/events/42/sessions">
          Sessions
        </NextLink>
      </li>
      <li>
        <NextLink look="plain" href="/events/42/attendees">
          Attendees
        </NextLink>
      </li>
    </ul>
  </nav>
);

/**
 * Disabled with a reason: it can't be followed, and hovering or focusing it
 * says why.
 */
const DisabledWithReason = () => (
  <NextLink
    href="/events/42/report"
    disabledWithReason="Opens once the event has ended"
  >
    Attendance report
  </NextLink>
);

/**
 * `onNavigate` runs before a route change and can cancel it with
 * `event.preventDefault()`. Here it blocks the navigation while the title has
 * unsaved changes, and a visible message says why.
 */
const GuardedNavigation = () => {
  const [saved, setSaved] = useState('Design review');
  const [title, setTitle] = useState(saved);
  const [blocked, setBlocked] = useState(false);
  const unsaved = title !== saved;

  return (
    <div className="flex-col-gap-2 items-start">
      <Input
        label="Event title"
        autoComplete="off"
        value={title}
        onChange={setTitle}
      />
      <Button
        variant="base"
        onClick={() => {
          setSaved(title);
          setBlocked(false);
        }}
      >
        Save
      </Button>
      <NextLink
        look="plain"
        href="/events"
        onNavigate={(event) => {
          if (!unsaved) return;
          event.preventDefault();
          setBlocked(true);
        }}
      >
        Back to all events
      </NextLink>
      <p role="status">{blocked ? 'Save your changes before leaving.' : ''}</p>
    </div>
  );
};

/**
 * A route styled as a button: `Button as={NextLink}` with `href`. A disabled
 * one renders an anchor without `href`, so it can't be followed; give a
 * reason.
 */
const RouteAsButton = () => (
  <div className="flex-row-gap-2 flex-wrap">
    <Button as={NextLink} href="/events/new" leftIcon={<Plus />}>
      Create event
    </Button>
    <Button
      as={NextLink}
      href="/events/42/report"
      variant="base"
      disabledWithReason="Opens once the event has ended"
    >
      Attendance report
    </Button>
  </div>
);

export default function NextLinkRecipe() {
  return (
    <div className="flex-col-gap-4 items-start">
      <InText />
      <KeepScroll />
      <ReplaceHistory />
      <Navigation />
      <DisabledWithReason />
      <GuardedNavigation />
      <RouteAsButton />
    </div>
  );
}

// packages/ui/src/Radio/Radio.recipe.tsx
// Covers: Radio, RadioGroup

/**
 * Radio and RadioGroup: one choice from a few visible options, like a ticket
 * type. RadioGroup is the form field, with label, help text and error; each
 * Radio's children are its label. Arrow keys move between radios and choose;
 * the group is one tab stop.
 *
 * When not to use:
 * - Any number of choices: CheckboxGroup. One yes/no: Checkbox.
 * - Short choices in a toolbar or filter bar: ChipGroup. Choices with a
 *   description or picture: CardGroup.
 * - More than about 7 options: Select.
 *
 * Pitfalls:
 * - A Radio renders only inside a RadioGroup, and each needs a `value`.
 * - The group needs a name: `label`, `aria-labelledby` or `aria-label`.
 * - It's controlled: `value` and `onChange`, or `{...field}` from Controller.
 *   Set `required` through the Controller's `rules`.
 * - RadioGroup adds no layout: lay the radios out with its `className`.
 * - Say why a radio can't be chosen with `disabledWithReason`: it stays
 *   reachable by arrow keys, so the reason is read.
 */
import { Button } from '@packages/ui/Button';
import { Controller, Form } from '@packages/ui/Form';
import { Radio, RadioGroup } from '@packages/ui/Radio';
import { Section } from '@packages/ui/Section';
import React, { useState } from 'react';
import { useForm } from 'react-hook-form';

// Setup: stand-ins for your app's data and requests, not part of the pattern.
// Stands in for a request to a server.
const register = (registration: Registration) =>
  new Promise((resolve) => setTimeout(resolve, 400, registration));

// Usage: the patterns to copy.
type Registration = { ticket: string };

/**
 * In a form: RadioGroup renders through Controller with `{...field}`. `rules`
 * makes it required, so the label shows the mark and a failed submit shows the
 * error and focuses the group. A radio that can't be chosen says why.
 */
const TicketForm = () => {
  const [status, setStatus] = useState('');
  const { control, handleSubmit } = useForm<Registration>({
    defaultValues: { ticket: '' },
  });

  const submit = async (registration: Registration) => {
    await register(registration);
    setStatus(`Registered with a ${registration.ticket} ticket`);
  };

  return (
    <Form
      onSubmit={handleSubmit(submit)}
      actions={<Button type="submit">Register</Button>}
    >
      <Controller
        name="ticket"
        control={control}
        rules={{ required: 'Choose a ticket' }}
      >
        {({ field }) => (
          <RadioGroup
            label="Ticket"
            helpText="You can change it until the day before."
            {...field}
            className="flex-col-gap-2"
          >
            <Radio value="general">General admission</Radio>
